    <!-- 费用明细 -->
    <view v-if="!isLoading" class="card fee-detail">
      <view class="title">
        <text class="iconfont icon-list"> 费用明细</text>
      </view>
      <!-- 修改：费用明细显示从缓存获取的金额 -->
      <view class="fee-item">
        陪诊服务费用 <text class="price">¥{{ formatAmount(orderData.amount) }}</text>
      </view>
      <view class="fee-item">优惠券 <text class="discount">-¥0.00</text></view>
      <view class="total">
        总计 <text class="total-price">¥{{ formatAmount(orderData.amount) }}</text>
      </view>
    </view>
    <!-- 支付方式 -->
    <view v-if="!isLoading" class="card payment-method">
      <view class="title">
        <text class="iconfont icon-pay"> 选择支付方式</text>
      </view>
      <!-- 修改点：绑定和使用 payMethod -->
      <radio-group @change="onPaymentChange" :value="payMethod">
        <view class="payment-option">
          <radio value="wechat" :checked="payMethod === 'wechat'" />
          <view class="pay-icon">
            <text class="iconfont icon-wechat"> 微信支付</text>
          </view>
        </view>
        <view class="payment-option">
          <radio value="alipay" :checked="payMethod === 'alipay'" />
          <view class="pay-icon">
            <text class="iconfont icon-alipay"> 支付宝支付</text>
          </view>
        </view>
        <view class="payment-option">
          <radio value="unionpay" :checked="payMethod === 'unionpay'" />
          <view class="pay-icon">
            <text class="iconfont icon-unionpay"> 银联支付</text>
          </view>
        </view>
      </radio-group>
    </view>
    <!-- 协议勾选 (保留UI元素，但不再控制按钮) -->
    <view v-if="!isLoading" class="agreement">
      <checkbox class="check-box" />
      <text class="agreement-text">我已阅读并同意<text class="link" @click="goToAgreement">《陪诊服务协议》</text> 和<text class="link" @click="goToPrivacy">《隐私政策》</text></text>
    </view>
    <!-- 底部支付栏 -->
    <view v-if="!isLoading" class="footer">
      <view class="real-price">实付款：<text class="price">¥{{ formatAmount(orderData.amount) }}</text></view>
      <!-- 修改点：移除 :disabled 和动态类 -->
      <button class="confirm-btn" @click="confirmPay">确认支付</button>
    </view>
  </view>
</template>

<script>
// 【重要】引入 api.js 文件中的 get 方法用于获取数据
// import {get} from '@/utils/api.js'; // 不再需要调用后端接口
export default {
    data() {
        return {
            // --- 保持原有的 orderData 字段结构不变 ---
            orderData: {
                attendantId: 0,
                attendantName: '',
                attendantPhone: '',
                contactPerson: '',
                contactPhone: '',
                orderNo: '',
                orderStatus: '',
                payMethod: 'wechat', // 默认支付方式 (注意：这里现在是 orderData.payMethod)
                qrCode: '',
                serviceTypes: [], // --- 保留前端原有的字段 ---
                amount: 0, // 从缓存或计算填充
                hospital: '', // 从缓存填充
                serviceTime: '', // 从缓存填充
                specialRequirements: '', // 从缓存填充
                avatarUrl: '', // 新增：陪诊师头像URL
                selectedServices: [], // 新增：从上一页传来的服务类型
                // --- 新增：用于显示症状描述的字段 ---
                operationName: '', // 手术名称
                selectedSymptoms: [], // 选中的症状索引
                symptomsList: ['胸痛', '头痛', '发热', '呼吸困难', '恶心呕吐', '腹痛', '头晕'], // 症状列表
                otherNeeds: '', // 其他需求
                // ---
            },
            remark: '', // 用户输入的补充备注
            showInvoice: false, // 发票展开状态
            // --- 修改点：移除 agree 字段 ---
            // agree: false, // 协议勾选状态 (不再需要)
            // --- 修改点：定义根级别的 payMethod 并初始化 ---
            payMethod: 'wechat', // 根级别的支付方式，默认值
            isLoading: false, // 页面加载状态
            // isFetchingDetail: false // 标志位，不再需要
        };
    },
    // computed: {
    //     // 计算属性：根据 selectedServices 和 serviceTime 动态计算金额 (已移除，直接使用缓存的金额)
    //     // computedAmount() { ... } // 删除此计算属性
    // },
    onLoad(options) {
        console.log('【OrderConfirmPage】页面加载参数:', options);
        let storedData = null;
        try {
            // 1. 从本地缓存读取由 ServiceCompanionSelect 存储的完整订单确认数据
            storedData = uni.getStorageSync('orderConfirmData');
            console.log('【OrderConfirmPage】从 Storage 读取到完整订单数据:', storedData);
        } catch (e) {
            console.warn('【OrderConfirmPage】从 Storage 读取完整订单数据失败', e);
        }

        if (storedData) {
            // 2. 如果缓存中有数据，直接使用它来填充 orderData 和其他字段
            console.log('【OrderConfirmPage】使用缓存中的订单数据填充页面');
            this.orderData = {
                ...this.orderData,
                ...storedData
            };
            this.remark = storedData.remark || '';
            this.payMethod = storedData.payMethod || 'wechat';
            this.orderData.payMethod = this.payMethod; // 保持同步
            // 确保 selectedServices 被填充，以便计算金额 (如果需要)
            if (storedData.selectedServices) {
                this.orderData.selectedServices = storedData.selectedServices;
            }
            // 如果缓存中没有 selectedServices，尝试从其他可能的来源获取（例如，如果它在上一个页面缓存中）
            // 这里假设 selectedServices 在 orderConfirmData 中，如果不是，需要调整上一步的存储逻辑
        } else {
            // 3. 如果缓存中没有数据，则使用示例数据作为 fallback
            console.warn('【OrderConfirmPage】未找到缓存的订单数据，使用示例数据');
            const exampleData = {
                orderNo: 'PZ202512250001_EXAMPLE',
                amount: 19800, // 示例值（单位：分）
                attendantName: '示例陪诊师',
                hospital: '示例医院', // 示例医院
                serviceTime: '2025-12-25 09:00', // 示例时间 (就诊时间)
                contactPerson: '示例就诊人',
                payMethod: 'wechat', // 示例支付方式
                qrCode: '', // 示例数据可能没有二维码
                avatarUrl: '/static/default_avatar.png', // 示例头像
                selectedServices: ['consult', 'exam'], // 示例服务类型
                // --- 示例：症状相关数据 ---
                operationName: '阑尾切除术',
                selectedSymptoms: [2], // ['发热']
                otherNeeds: '希望陪诊师有经验',
                // ---
            };
            this.orderData = {
                ...this.orderData,
                ...exampleData
            };
            this.payMethod = exampleData.payMethod; // 同步根级别
        }
    },
    methods: {
        // /** * 调用后端接口获取订单详情 * @param {string} orderNo - 订单号 */
        // async fetchOrderDetail(orderNo) { // ... 原来的 fetchOrderDetail 逻辑被移除 ... },
        /** * 处理支付方式变更 * @param {Object} e - 事件对象 */
        onPaymentChange(e) {
            // 修改点：更新根级别的 payMethod
            this.payMethod = e.detail.value;
            // 同时更新 orderData.payMethod 保持一致性
            this.orderData.payMethod = e.detail.value;
            console.log('【支付方式变更】', this.payMethod);
        },
        // /** // * 移除协议勾选处理函数 // * @param {Object} event - 事件对象 // */
        // onAgreeChange(event) { // ... 之前的逻辑 ... },
        /** * 确认支付 (修改版 - 移除协议检查) */
        confirmPay() {
            // 移除了 if (!this.agree) { ... } 检查
            console.log('【开始支付流程】', {
                orderNo: this.orderData.orderNo, // 使用根级别的 payMethod
                paymentMethod: this.payMethod,
                remark: this.remark
            });

            // 将当前订单状态（包括支付方式、备注等）更新到缓存，供下一步使用
            // 注意：使用缓存中的金额，不再重新计算
            const currentOrderData = {
                ...this.orderData,
                // amount: this.computedAmount, // 删除此行，使用缓存中的 amount
                payMethod: this.payMethod,
                remark: this.remark
            };
            uni.setStorageSync('orderConfirmData', currentOrderData);

            // --- 示例：跳转到支付结果或下一个页面 ---
            // 请将 '/pages/next/next' 替换为您实际要跳转的页面路径
            uni.navigateTo({
                url: '/pages/PaymentSuccessPage/PaymentSuccessPage'
            });
            // ... 您原本在这里可能有的实际支付逻辑 ...
            // 例如调用支付接口
            // uni.showToast({ title: '模拟支付触发', icon: 'none' });
        },
        /** * 切换发票信息显示 */
        toggleInvoice() {
            this.showInvoice = !this.showInvoice;
        },
        /** * 获取头像URL (示例) */
        getAvatarUrl() {
            // 返回默认头像或根据 orderData.attendantId 生成URL
            return '/static/default_avatar.png'; // 替换为你的默认头像路径
        },
        /** * 跳转到协议页面 (示例) */
        goToAgreement() {
            uni.navigateTo({ url: '/pages/agreement/service' }); // 替换为你的协议页面路径
        },
        /** * 跳转到隐私政策页面 (示例) */
        goToPrivacy() {
            uni.navigateTo({ url: '/pages/agreement/privacy' }); // 替换为你的隐私政策页面路径
        },
        /** * 格式化金额 (分 -> 元) * @param {number} amountInCents - 以分为单位的金额 * @returns {string} 格式化后的金额字符串 */
        formatAmount(amountInCents) {
            if (typeof amountInCents !== 'number' || isNaN(amountInCents)) {
                return '0.00';
            }
            return (amountInCents / 100).toFixed(2);
        },
        /** * 编辑医院 */
        editHospital() {
            uni.showModal({
                title: '修改医院',
                editable: true,
                placeholderText: this.orderData.hospital || '请输入医院名称',
                success: (res) => {
                    if (res.confirm && res.content.trim() !== '') {
                        this.orderData.hospital = res.content.trim();
                        this.updateCache();
                    }
                }
            });
        },
        /** * 编辑时间 */
        editTime() {
            // 分割当前时间字符串为日期和时间部分
            let initialDate = '2025-01-01';
            let initialTime = '09:00';
            if (this.orderData.serviceTime) {
                const parts = this.orderData.serviceTime.split(' ');
                if (parts.length >= 2) {
                    initialDate = parts[0];
                    initialTime = parts[1];
                }
            }

            uni.showActionSheet({
                itemList: ['修改日期', '修改时间'],
                success: (res) => {
                    if (res.tapIndex === 0) {
                        // 修改日期
                        uni.showDatePicker({
                            value: initialDate,
                            success: (dateRes) => {
                                const newDate = dateRes.value;
                                const timePart = this.orderData.serviceTime ? this.orderData.serviceTime.split(' ')[1] : '09:00';
                                this.orderData.serviceTime = `${newDate} ${timePart}`;
                                this.updateCache();
                            }
                        });
                    } else if (res.tapIndex === 1) {
                        // 修改时间
                        uni.showTimePicker({
                            value: initialTime,
                            success: (timeRes) => {
                                const newTime = timeRes.value;
                                const datePart = this.orderData.serviceTime ? this.orderData.serviceTime.split(' ')[0] : '2025-01-01';
                                this.orderData.serviceTime = `${datePart} ${newTime}`;
                                this.updateCache();
                            }
                        });
                    }
                }
            });
        },
        /** * 编辑就诊人 */
        editPatient() {
            uni.showModal({
                title: '修改就诊人',
                editable: true,
                placeholderText: this.orderData.contactPerson || '请输入就诊人姓名',
                success: (res) => {
                    if (res.confirm && res.content.trim() !== '') {
                        this.orderData.contactPerson = res.content.trim();
                        this.updateCache();
                    }
                }
            });
        },
        /** * 编辑症状 (示例) */
        editSymptom() {
            // 症状编辑较为复杂，这里提供一个简单的输入框示例
            // 实际项目中可能需要更复杂的多选或分类界面
            uni.showModal({
                title: '修改症状描述',
                editable: true,
                placeholderText: this.getSymptomDescription() || '请输入症状描述',
                success: (res) => {
                    if (res.confirm && res.content.trim() !== '') {
                        // 这里可以将用户输入的文本作为新的症状描述
                        // 为了与现有逻辑兼容，可以将其存入 otherNeeds 或创建新字段
                        // 为了简单起见，存入 otherNeeds
                        this.orderData.otherNeeds = res.content.trim();
                        this.updateCache();
                    }
                }
            });
        },
        /** * 更新缓存 */
        updateCache() {
            // 将修改后的 orderData 更新到缓存
            const currentOrderData = {
                ...this.orderData,
                payMethod: this.payMethod,
                remark: this.remark
            };
            uni.setStorageSync('orderConfirmData', currentOrderData);
            console.log('【OrderConfirmPage】数据已更新到缓存:', currentOrderData);
        },
        // --- 新增：获取头像完整路径 ---
        getImagePath(avatarFileName) {
            // 如果 avatarUrl 是完整的网络路径，则直接返回
            if (avatarFileName && (avatarFileName.startsWith('http://') || avatarFileName.startsWith('https://'))) {
                return avatarFileName;
            }
            // 否则，认为是相对路径，拼接 /static/
            return avatarFileName ? `/static/${avatarFileName}` : this.getAvatarUrl(); // 如果为空，则使用默认头像
        },
        // ---
        // --- 新增：获取症状描述文本 ---
        getSymptomDescription() {
            // 从缓存数据中获取手术名、选中的症状索引和其它需求
            const { operationName, selectedSymptoms, otherNeeds, symptomsList } = this.orderData;
            const parts = [];

            if (operationName) {
                parts.push(operationName);
            }

            if (selectedSymptoms && selectedSymptoms.length > 0) {
                const symptomNames = selectedSymptoms.map(index => symptomsList[index]).filter(name => name);
                if (symptomNames.length > 0) {
                    parts.push(...symptomNames);
                }
            }

            if (otherNeeds) {
                parts.push(otherNeeds);
            }

            // 使用逗号连接所有部分
            return parts.join(', ');
        }
        // ---
    }
};
</script>

